const ПРЯМО_СРАВНИТЬ = /^\s*(сравни|сравнить|сопоставь|сравнение)(?![а-я])/i;
const ПРЯМО_ВОПРОС = /^\s*(как(?:им образом)?\s+(?!в таблице\b)[а-яё]|что\s+(такое|значит|означает)|где\s+(находится|включается|искать|найти|лежит)|зачем|почему|можно ли|умеет ли|поддерживается ли|чем отлича|в ч[её]м разница|расскажи|объясни|подскажи\s+(про|о|об|как))/i;
const ПРО_СЕБЯ = /(что ты умеешь|что умеешь|что ты можешь|твои возможности|справка)/i;
async function сделать(намерение, исходный, уверенность){
