}
ответ = typeof ответ === 'string' ? ответ : (ответ && ответ.ответ) || 'Готово';
if(последнее && намерение !== 'отменить') ответ += '. ' + (последнее.пометка || 'Это «Отменить» приложения не снимает') + ' — скажите «отмени», уберу сам';
