строки.push(н + '«' + ш.текст + '» — не понял' + (ш.класс !== 'нет' && ш.варианты.length ? ' (возможно: ' + ш.варианты.map(x => НАМЕРЕНИЯ[x].что).join(', ') + ')' : ''));
