const БУКВА = c => { let s = ''; c++; while(c > 0){ const m = (c - 1) % 26; s = String.fromCharCode(65 + m) + s; c = Math.floor((c - 1) / 26); } return s; };
const АДР = (r, c) => БУКВА(c) + (r + 1);
