очки.push({n, v: (ключ[n] / макс + 0.3 * рукКосинус(и, темы, нт, n)) * бонус, ключ: ключ[n]});
}
очки.sort((a, b) => b.v - a.v);
if(!очки.length || (очки[0].ключ <= 0 && очки[0].v < 0.25))
отказ('В руководстве такого не нашёл. Спросите иначе — или откройте руководство: там оглавление и поиск.');
const лучший = очки[0], путь = д.разделы[и.места[лучший.n].с].п;
const соседи = [];
for(const о of очки.slice(1)){
const п = д.разделы[и.места[о.n].с].п;
if(п !== путь && !соседи.includes(п)) соседи.push(п);
if(соседи.length >= 2) break;
}
return 'Руководство, раздел **' + путь + '**\n\n' + и.тексты[лучший.n].trim()
+ (соседи.length ? '\n\nРядом по теме: ' + соседи.map(x => '«' + x + '»').join(', ') + '.' : '')
+ '\n\n_По руководству от ' + д.дата + ' — полный текст во вкладке «Справка»._';
};
